import (
	"net/url"
	"strings"
)

/**
Check if the provided target URL string is within the provided domain.
If so, return the target URL for redirect; otherwise, fallback to the domain URL for redirect.
Use https protocol.

Examples:

	getTargetForRedirect("https://music.example.com", "example.com") -> "https://music.example.com"
	getTargetForRedirect("https://example.com/service", "example.com") -> "https://example.com/service"
	getTargetForRedirect("https://blog.example.com/posts", "example.com") -> "https://blog.example.com/posts"
	getTargetForRedirect("https://another.com", "example.com") -> "https://example.com"

@param target: The target URL string.
@param domain: The domain string, without protocol.

@return The URL string for redirect.
*/
func getTargetForRedirect(target string, domain string) string {
	// Ensure the domain is not empty to prevent unexpected behavior.
	if domain == "" {
		return "https://" + domain
	}

	targetURL, err := url.Parse(target)
	if err != nil {
		// If target URL is invalid, fallback to the domain URL with https.
		return "https://" + domain
	}

	// Ensure the target URL has a scheme, defaulting to https if not present.
	if targetURL.Scheme == "" {
		targetURL.Scheme = "https"
	}

	// If the scheme is not https, force it to https.
	if targetURL.Scheme != "https" {
		targetURL.Scheme = "https"
	}

	targetHost := targetURL.Hostname()

	// Check if the target hostname is the same as the domain or a subdomain of it.
	// We use strings.HasSuffix to check for subdomains.
	// We also need to ensure that the targetHost is not just a part of another domain.
	// For example, if domain is "example.com", "sub.example.com" should match,
	// but "myexample.com" should not.
	if targetHost == domain || strings.HasSuffix(targetHost, "."+domain) {
		// If the target URL is within the domain, return the modified target URL.
		return targetURL.String()
	}

	// If the target URL is not within the domain, fallback to the domain URL with https.
	return "https://" + domain
}
